def _sign_sessions_path(self, wallet_id: str) -> str:
    _check_id("wallet_id", wallet_id)
    return os.path.join(self._sign_sessions_dir, wallet_id + ".json")

@staticmethod
def _session_share_shape_ok(entry: object) -> bool:
    """已收份额条目形状：share_id 为合法标识、signature 为 hex 字符串
    且解码恰为 64 字节 Ed25519 份额签名。"""
    if not isinstance(entry, dict):
        return False
    share_id = entry.get("share_id")
    signature_hex = entry.get("signature")
    if not isinstance(share_id, str) or not _SAFE_SHARE_ID.match(share_id):
        return False
    if not isinstance(signature_hex, str):
        return False
    try:
        signature = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    return len(signature) == 64

def _session_record_shape_ok(self, key: str, record: object) -> bool:
    """签名会话记录形状的严格校验（损坏文件 fail-closed 用）。

    要求：id 为安全标识且与键一致；message 为非空字符串；
    timeout_seconds 为非布尔正整数；expires_at 为字符串；state 仅
    collecting/ready/signed/expired；shares 为条目数组，share_id
    不重复且为当前记录的份额；signed 时必须带 128 字节聚合签名；
    collecting/ready/expired 不得带签名。"""
    if not isinstance(record, dict):
        return False
    if record.get("id") != key or not _valid_safe_id(key):
        return False
    message = record.get("message")
    if not isinstance(message, str) or not message:
        return False
    timeout = record.get("timeout_seconds")
    if not _is_plain_int(timeout) or timeout <= 0:
        return False
    if not isinstance(record.get("expires_at"), str):
        return False
    if not isinstance(record.get("created_at"), str):
        return False
    state = record.get("state")
    if state not in ("collecting", "ready", "signed", "expired"):
        return False
    expected = record.get("share_ids")
    if not isinstance(expected, list) or len(expected) != 2:
        return False
    if any(
        not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
        for sid in expected
    ):
        return False
    if len(set(expected)) != 2:
        return False

# ---- 建钱包 ---------------------------------------------------------

def create_wallet(self, wallet_id: object, shares: object) -> dict:
    if not isinstance(wallet_id, str) or not wallet_id:
        raise ServiceError(400, "wallet_id must be a non-empty string")
    # bool 是 int 的子类，必须先排除；2.0 == 2，必须要求真正的 int
    if not isinstance(shares, int) or isinstance(shares, bool):
        raise ServiceError(400, "shares must equal 2")
    if shares != REQUIRED_SHARES:
        raise ServiceError(400, "shares must equal 2")
    try:
        share_keys = [crypto.generate_share_key(sid) for sid in SHARE_IDS]
        # 跨进程防重：同一 data-dir 上多个服务进程并发建同名钱包时，
        # 只有一个能在事务锁内提交成功
        with self._wallet_lock(wallet_id):
            self._store.create_wallet(
                wallet_id, share_keys, _utc_now_iso()
            )
    except DuplicateWalletError:
        raise ServiceError(409, f"wallet {wallet_id!r} already exists")
    except ValueError:
        # wallet_id 含非法字符
        raise ServiceError(400, "invalid wallet_id")
    public_key = crypto.combine_public_keys(
        [k.public_bytes for k in share_keys]
    )
    return {
        "wallet_id": wallet_id,
        "public_key": public_key.hex(),
        "share_ids": list(SHARE_IDS),
    }

# ---- 查询钱包 -------------------------------------------------------

def get_wallet(self, wallet_id: str) -> dict:
    try:
        with self._wallet_lock(wallet_id):
            # 查询前先自愈他进程崩溃遗留的激活现场，绝不把换了一半
            # 的公钥/份额经 GET 暴露出去
            self._heal_wallet(wallet_id)
            record = self._store.get_wallet(wallet_id)
    except CorruptDataError:
        # 钱包元数据损坏：fail-closed（由 HTTP 边界转 503）
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")
    if record is None:
        raise ServiceError(404, f"wallet {wallet_id!r} not found")
    return {
        "wallet_id": record["wallet_id"],
        "public_key": record["public_key"],
        "created_at": record["created_at"],
    }

