@staticmethod
def _map_wallet_public_key(
    mapping: dict, share_ids: object, public_key_hex: object
) -> None:
    """把"钱包公钥（两份份额公钥有序拼接）"按下标映射到各 share_id。"""
    if not isinstance(public_key_hex, str):
        return
