            json.dump(data, f)

    def _tamper_session(self, mutate):
        path = self._session_file()
        data = self._read(path)
        mutate(data["s1"])
        self._write(path, data)

    def _tamper_audit(self, mutate):
        path = self._audit_file()
        data = self._read(path)
        mutate(data["events"])
        self._write(path, data)

    def _assert_fails_closed_and_preserved(self, path):
